export const enum AgentModel {
  Claude37Sonnet = 'claude-3.7-sonnet',
  Claude35Sonnet = 'claude-3.5-sonnet',
}

export const enum ModelName {
  ClaudeSonnet37 = 'ClaudeSonnet3_7',
  ClaudeSonnet35 = 'ClaudeSonnet',
}

export const agentModelMap: Record<AgentModel, ModelName> = {
  [AgentModel.Claude37Sonnet]: ModelName.ClaudeSonnet37,
  [AgentModel.Claude35Sonnet]: ModelName.ClaudeSonnet35,
};

export const getModelName = (agentModel: string) => {
  return agentModelMap[agentModel as AgentModel] || ModelName.ClaudeSonnet37;
};
