import { ReactComponent as FileSVG } from '@/assets/common/file.svg';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import useRegisterMessage from '@/services/JsBridge/useRegisterMessage';
import { useAgenticStore, useGlobalStore } from '@/store';
import { CloseOutlined } from '@ant-design/icons';
import { message, Popover } from 'antd';
import classNames from 'classnames';
import React, { useCallback } from 'react';
import Highlight from 'react-highlight';
import { v4 as uuid } from 'uuid';
import styles from './index.module.less';

export interface SelectedCodeItem {
  code: string; // 选中的代码
  fullContent: string; // 代码文件的完整内容
  source: string; // 代码文件，相对路径
  fsPath: string; // 代码文件，绝对路径
  language: string; // 代码语言
  startLine: number;
  endLine: number;
  startOffset: number;
  endOffset: number;
  id?: string;
  name?: string; // 文件名
}

export const renderSelectedCodeCard = (
  item: SelectedCodeItem,
  {
    closeFile,
  }: {
    closeFile?: (item: SelectedCodeItem) => void;
    theme: string;
  },
) => {
  const handleOpenTargetCode = (item: SelectedCodeItem) => {
    jsBridgePostMessage({
      command: 'openFileAndSelect',
      data: {
        fileUri: item.fsPath,
        startLine: item.startLine - 1,
        startOffset: item.startOffset,
        endLine: item.endLine - 1,
        endOffset: item.endOffset,
      },
    });
  };
  return (
    <Popover
      key={item.id}
      title={item.source}
      content={<Highlight>{item.code}</Highlight>}
    >
      <div
        className={styles.extag}
        onClick={() => handleOpenTargetCode?.(item)}
      >
        <div className={styles.iconWrapper}>
          <FileSVG />
        </div>
        <span>
          {item.name ?? item.source?.split('/')?.pop()}
          {`(${item.startLine}-${item.endLine})`}
        </span>
        {closeFile && (
          <b
            onClick={(e) => {
              e.stopPropagation();
              closeFile?.(item);
            }}
          >
            <CloseOutlined />
          </b>
        )}
      </div>
    </Popover>
  );
};

const SelectedCodeList: React.FC = () => {
  const { selectedCodeList, setSelectedCodeList } = useAgenticStore();
  const {
    pluginConfig: { theme, mode },
  } = useGlobalStore();

  const closeFile = (item: SelectedCodeItem) => {
    const newList = selectedCodeList.filter((file) => file.id !== item.id);
    setSelectedCodeList(newList);
  };
  const onAddToChat = useCallback(
    (data: SelectedCodeItem) => {
      data.id = uuid();
      data.name = data.fsPath?.split('/')?.pop();
      // 根据文件起始行号去重
      const isExist = selectedCodeList.some(
        (item) =>
          item.fsPath === data.fsPath &&
          item.startLine === data.startLine &&
          item.endLine === data.endLine,
      );
      if (isExist) {
        message.warning('该代码块已添加');
        return;
      }
      setSelectedCodeList(selectedCodeList.concat(data));
    },
    [selectedCodeList],
  );

  useRegisterMessage('addToChat', onAddToChat);

  if (mode !== 'agent' || !selectedCodeList.length) return null;
  return (
    <div className={classNames(styles.expandPanelTagArea, styles[theme])}>
      {selectedCodeList.map((item) =>
        renderSelectedCodeCard(item, { theme, closeFile }),
      )}
    </div>
  );
};

export default SelectedCodeList;
