import { message } from 'antd';
import { useCallback } from 'react';

// 支持的图片格式
const supportImgFormat = [
  'image/jpeg',
  'image/jpg',
  'image/png',
  'image/gif',
  'image/webp',
  'image/bmp',
  'image/svg+xml',
];

const MAX_FILES = 3;
const MAX_FILE_SIZE_MB = 20;

export default (imgArr: string[], setImgArr: (urls: string[]) => void) => {
  const validateImage = useCallback((file: File) => {
    const fileSizeInMB = file.size / 1024 / 1024;

    if (!supportImgFormat.includes(file.type)) {
      message.warning('不支持该格式');
      return false;
    }

    if (fileSizeInMB > MAX_FILE_SIZE_MB) {
      message.warning(`图片大小不能超过 ${MAX_FILE_SIZE_MB}MB`);
      return false;
    }

    return true;
  }, []);

  const readFile = useCallback((file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = () => reject(new Error('读取文件失败'));
      reader.readAsDataURL(file);
    });
  }, []);

  const processFiles = useCallback(
    async (files: FileList | File[]) => {
      if (imgArr.length >= MAX_FILES) {
        message.warning(`最多只能上传${MAX_FILES}张图片`);
        return;
      }

      const remainingSlots = MAX_FILES - imgArr.length;
      const filesToProcess = Array.from(files)
        .slice(0, remainingSlots)
        .filter((file) => file.type.startsWith('image/'));

      const processedImages: string[] = [];

      for (const file of filesToProcess) {
        if (validateImage(file)) {
          try {
            const base64 = await readFile(file);
            processedImages.push(base64);
          } catch (error) {
            console.error('读取文件失败:', error);
            message.error('读取文件失败');
          }
        }
      }

      if (processedImages.length > 0) {
        setImgArr([...imgArr, ...processedImages]);
      }
    },
    [imgArr, setImgArr, validateImage, readFile],
  );

  return { processFiles };
};
