import React, { useEffect, useState } from 'react';

import {
  getChannelList,
  ProvidersData,
  saveModelConfig,
} from '@/services/Api/agentic';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { useGlobalStore } from '@/store';
import {
  Input as AntdInput,
  Button,
  Divider,
  Form,
  message,
  Popover,
  Select,
} from 'antd';
import styles from './index.module.less';

interface ProviderPopoverProps {
  open: boolean;
  onClose: () => void;
  anchor: React.ReactNode;
}

const ProviderPopover: React.FC<ProviderPopoverProps> = ({
  open,
  onClose,
  anchor,
}) => {
  const { projectConfig, setPluginConfig, setDisplayModel, pluginConfig } =
    useGlobalStore();
  const {
    sideCarIDEInfo: { sideCarPort },
  } = projectConfig;

  const [providerData, setProviderData] = useState<ProvidersData>();
  const [loading, setLoading] = useState<boolean>(false);

  const providerKeys = Object.keys(providerData?.providers || {});
  const [form] = Form.useForm();
  const [selectedProvider, setSelectedProvider] = useState<string>(
    providerKeys[0] || '',
  );
  const [selectedModel, setSelectedModel] = useState<string>('');

  // 从provider数据中提取已保存的配置值
  const getSavedConfigValues = (providerName: string) => {
    const providerConfig = providerData?.providers?.[providerName];
    if (!providerConfig?.provider) return {};

    const savedValues: Record<string, string> = {};
    providerConfig.provider.forEach((field: any) => {
      if (field.key_value) {
        savedValues[field.key_name] = field.key_value;
      }
    });
    return savedValues;
  };

  // 弹窗打开时请求通道列表数据
  useEffect(() => {
    const fetchChannelList = async () => {
      setLoading(true);
      const res = await getChannelList(`http://localhost:${sideCarPort}`);
      if (res.success) {
        setProviderData(res.data);

        // 在获取数据成功后立即设置插件配置
        const data = res.data;
        const providerKeys = Object.keys(data?.providers || {});

        // 如果 default_provider 有值就用，没有就取第一个作为默认厂商
        const defaultProvider: string =
          data.default_provider || providerKeys[0] || '';

        const currentProviderConfig = data.providers?.[defaultProvider];
        // 如果 default_model 有值就用，没有就取当前默认厂商下的默认模型
        const defaultModel: string =
          data.default_model || currentProviderConfig?.default_model || '';

        // 获取已保存的配置值
        const getSavedConfigValues = (providerName: string) => {
          const providerConfig = data?.providers?.[providerName];
          if (!providerConfig?.provider) return {};

          const savedValues: Record<string, string> = {};
          providerConfig.provider.forEach((field: any) => {
            if (field.key_value) {
              savedValues[field.key_name] = field.key_value;
            }
          });
          return savedValues;
        };

        const savedValues = getSavedConfigValues(defaultProvider);

        // 设置 displayModel
        if (defaultProvider && defaultModel) {
          setDisplayModel(`${defaultProvider}:${defaultModel}`);

          // 检查该厂商的 API Key 是否都不为空
          const requiredFields = currentProviderConfig?.provider || [];
          const hasAllRequiredKeys = requiredFields.every((field: any) => {
            const fieldValue = savedValues[field.key_name];
            return fieldValue && fieldValue.trim() !== '';
          });

          // 设置插件配置
          const pluginData = {
            model_name: defaultModel,
            selected_provider: defaultProvider,
            selected_provider_api_key: {
              [defaultProvider]: savedValues,
            },
          };

          setPluginConfig({
            ...pluginConfig,
            provider: pluginData,
          });

          // 只有当所有必需的 API Key 都不为空时才上报插件数据
          if (hasAllRequiredKeys) {
            jsBridgePostMessage({
              command: 'setPluginConfig',
              data: {
                provider: pluginData,
              },
            });
          }
        }
      } else {
        message.error('获取模型数据失败');
      }
      setLoading(false);
    };

    if (sideCarPort) {
      fetchChannelList();
    }
  }, [sideCarPort]);

  useEffect(() => {
    if (providerData) {
      // 如果 default_provider 有值就用，没有就取第一个作为默认厂商
      const defaultProvider: string =
        providerData.default_provider || providerKeys[0] || '';

      const currentProviderConfig = providerData.providers?.[defaultProvider];
      // 如果 default_model 有值就用，没有就取当前默认厂商下的默认模型
      const defaultModel: string =
        providerData.default_model || currentProviderConfig.default_model || '';

      setSelectedProvider(defaultProvider);
      setSelectedModel(defaultModel);

      // 设置默认的provider和model
      form.setFieldsValue({
        provider: defaultProvider,
        model: defaultModel || undefined,
      });

      // 使用从服务器获取的已保存配置值
      const savedValues = getSavedConfigValues(defaultProvider);
      if (Object.keys(savedValues).length > 0) {
        form.setFieldsValue(savedValues);
      }

      // 设置 displayModel
      if (defaultProvider && defaultModel) {
        setDisplayModel(`${defaultProvider}:${defaultModel}`);

        // 检查该厂商的 API Key 是否都不为空
        const requiredFields = currentProviderConfig?.provider || [];
        const hasAllRequiredKeys = requiredFields.every((field: any) => {
          const fieldValue = savedValues[field.key_name];
          return fieldValue && fieldValue.trim() !== '';
        });

        // 设置插件配置
        const pluginData = {
          model_name: defaultModel,
          selected_provider: defaultProvider,
          selected_provider_api_key: {
            [defaultProvider]: savedValues,
          },
        };

        setPluginConfig({
          ...pluginConfig,
          provider: pluginData,
        });

        // 只有当所有必需的 API Key 都不为空时才上报插件数据
        if (hasAllRequiredKeys) {
          jsBridgePostMessage({
            command: 'setPluginConfig',
            data: {
              provider: pluginData,
            },
          });
        }
      }
    }
  }, [providerData]);

  // 当前选中厂商的配置数据
  const providerConfig = providerData?.providers?.[selectedProvider] || {
    provider: [],
    modules: [],
    default_model: '',
  };
  const providerFields = providerConfig.provider || [];
  const modelList = providerConfig.modules || [];

  const handleProviderChange = (value: string) => {
    setSelectedProvider(value);

    // 获取新 provider 的配置信息
    const newProviderConfig = providerData?.providers?.[value];

    // 使用该 provider 的 default_model 作为默认值
    const defaultModel = newProviderConfig?.default_model || '';

    setSelectedModel(defaultModel);

    // 使用从服务器获取的已保存配置值
    const savedValues = getSavedConfigValues(value);

    if (Object.keys(savedValues).length > 0) {
      // 如果有保存的配置，使用保存的配置，但确保 model 使用默认值
      form.setFieldsValue({
        ...savedValues,
        provider: value,
        model: defaultModel || undefined,
      });
    } else {
      // 如果没有保存的配置，重置该provider的字段，但设置默认的 model
      const providerConfig = providerData?.providers?.[value];
      const providerFields = providerConfig?.provider || [];
      const resetFields = [...providerFields.map((item: any) => item.key_name)];
      form.resetFields(resetFields);

      // 单独设置 provider 和 model
      form.setFieldsValue({
        provider: value,
        model: defaultModel || undefined,
      });
    }

    // 检查该厂商的 API Key 是否都不为空
    const currentProviderConfig = providerData?.providers?.[value];
    const requiredFields = currentProviderConfig?.provider || [];
    const hasAllRequiredKeys = requiredFields.every((field: any) => {
      const fieldValue = savedValues[field.key_name];
      return fieldValue && fieldValue.trim() !== '';
    });

    const pluginData = {
      model_name: defaultModel,
      selected_provider: value,
      selected_provider_api_key: {
        [value]: savedValues,
      },
    };

    setPluginConfig({
      ...pluginConfig,
      provider: pluginData,
    });
    setDisplayModel(`${value}:${defaultModel}`);

    // 只有当所有必需的 API Key 都不为空时才上报插件数据
    if (hasAllRequiredKeys) {
      jsBridgePostMessage({
        command: 'setPluginConfig',
        data: {
          provider: pluginData,
        },
      });
    }
  };

  const handleModelChange = (value: string) => {
    setSelectedModel(value);
    form.setFieldsValue({ model: value });

    // 获取当前表单的所有值
    const currentValues = form.getFieldsValue();
    const { provider, model, ...configFields } = currentValues;

    // 检查该厂商的 API Key 是否都不为空
    const currentProviderConfig = providerData?.providers?.[selectedProvider];
    const requiredFields = currentProviderConfig?.provider || [];
    const hasAllRequiredKeys = requiredFields.every((field: any) => {
      const fieldValue = configFields[field.key_name];
      return fieldValue && fieldValue.trim() !== '';
    });

    const pluginData = {
      model_name: value,
      selected_provider: selectedProvider,
      selected_provider_api_key: {
        [selectedProvider]: configFields,
      },
    };

    setPluginConfig({
      ...pluginConfig,
      provider: pluginData,
    });
    setDisplayModel(`${selectedProvider}:${value}`);

    // 只有当所有必需的 API Key 都不为空时才上报插件数据
    if (hasAllRequiredKeys) {
      jsBridgePostMessage({
        command: 'setPluginConfig',
        data: {
          provider: pluginData,
        },
      });
    }
  };

  const handleSave = () => {
    form.validateFields().then(async (values) => {
      // 从 values 中分离出 provider 和 model，config 只保留提供商的具体配置
      const { provider, model, ...configFields } = values;

      // 将配置字段转换为后端需要的格式
      const providerInfo = Object.entries(configFields).map(
        ([key_name, key_value]) => ({
          key_name,
          key_value,
          key_description:
            providerFields.find((field: any) => field.key_name === key_name)
              ?.key_description || key_name,
        }),
      );

      // 服务端数据结构
      const serverData = {
        providerName: provider,
        providerInfo: JSON.stringify(providerInfo),
        model: model,
      };

      // 上报插件数据
      const pluginData = {
        model_name: model,
        selected_provider: provider,
        selected_provider_api_key: {
          [provider]: configFields,
        },
      };

      setPluginConfig({
        ...pluginConfig,
        provider: pluginData,
      });
      setDisplayModel(`${provider}:${model}`);

      jsBridgePostMessage({
        command: 'setPluginConfig',
        data: {
          provider: pluginData,
        },
      });

      // 调用 save 接口上报服务端数据
      saveModelConfig(serverData, `http://localhost:${sideCarPort}`);
      onClose();
    });
  };

  return (
    <Popover
      open={open}
      onOpenChange={(visible) => !visible && onClose()}
      content={
        loading ? (
          <div className={styles.modelConfigPopover__loading}>
            正在加载模型数据...
          </div>
        ) : (
          <div className={styles.modelConfigPopover__container}>
            <div className={styles.modelConfigPopover__content}>
              <Form
                form={form}
                layout="vertical"
                className={styles.modelConfigPopover__form}
              >
                <Form.Item label="API Provider" name="provider">
                  <Select
                    value={selectedProvider}
                    onChange={handleProviderChange}
                  >
                    {providerKeys.map((key: string) => (
                      <Select.Option key={key} value={key}>
                        {key}
                      </Select.Option>
                    ))}
                  </Select>
                </Form.Item>
                {providerFields.map((item: any) => (
                  <Form.Item
                    key={item.key_name}
                    label={item.key_description}
                    name={item.key_name}
                    rules={[
                      {
                        required: true,
                        message: `请输入${item.key_description}`,
                      },
                    ]}
                  >
                    <AntdInput.Password placeholder={item.key_description} />
                  </Form.Item>
                ))}
                <Divider />
                <Form.Item label="Model" name="model">
                  <Select
                    showSearch
                    value={selectedModel}
                    onChange={handleModelChange}
                    placeholder="请选择模型"
                    optionFilterProp="children"
                  >
                    {modelList.map((mod: any) => (
                      <Select.Option key={mod.name} value={mod.name}>
                        {mod.name}
                      </Select.Option>
                    ))}
                  </Select>
                </Form.Item>
                {selectedModel && (
                  <div className={styles.modelConfigPopover__modelInfo}>
                    {Object.entries(
                      modelList.find((m: any) => m.name === selectedModel) ||
                        {},
                    ).map(([k, v]) => (
                      <div
                        key={k}
                        className={styles.modelConfigPopover__modelInfoItem}
                      >
                        <b>{k}:</b> {String(v)}
                      </div>
                    ))}
                  </div>
                )}
              </Form>
            </div>
            <div className={styles.modelConfigPopover__footer}>
              <Button
                type="dashed"
                onClick={handleSave}
                className={styles.modelConfigPopover__saveButton}
              >
                保存
              </Button>
            </div>
          </div>
        )
      }
      trigger="click"
      placement="bottom"
    >
      {anchor}
    </Popover>
  );
};

export default ProviderPopover;
