import codeCollapse from '@/assets/chat/code-collapse.png';
import { ReactComponent as InsertSVG } from '@/assets/chat/insert.svg';
import { ReactComponent as ZoomSVG } from '@/assets/chat/zoom.svg';
import { ReactComponent as CopySVG } from '@/assets/common/copy.svg';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { useGlobalStore } from '@/store';
import copyToClipboard from '@/utils/copyToClipboard';
import { Tooltip } from 'antd';
import classNames from 'classnames';
import hljs from 'highlight.js';
import javascript from 'highlight.js/lib/languages/javascript';
import { FC, memo, ReactNode, useEffect, useRef, useState } from 'react';
import styles from './index.module.less';
import vueLanguage from './vue';

// highlight高亮不支持 vue 的md语法，手动支持下，react与javascript高亮很接近直接用javascript
hljs.registerLanguage('vue', vueLanguage);
hljs.registerLanguage('react', javascript);
hljs.registerLanguage('tsx', javascript);
hljs.registerLanguage('jsx', javascript);
hljs.configure({
  cssSelector: 'code',
  ignoreUnescapedHTML: true,
});

interface CodeRenderProps {
  children: Array<ReactNode>;
  inline?: boolean;
  className?: string;
}

const CodeRender: FC<CodeRenderProps> = (props) => {
  const { inline, className, children, ...rest } = props;
  const {
    pluginConfig: { isCodeBlockTruncated },
  } = useGlobalStore();
  const parsedChildren = String(children);
  const [collapse, setCollapse] = useState<boolean>(isCodeBlockTruncated);
  const [showMoreBtn, setShowMoreBtn] = useState<boolean>(false);
  const codeRef = useRef<HTMLPreElement>(null);

  useEffect(() => {
    const updateScrollHeight = () => {
      if (codeRef.current) {
        const showMore = codeRef.current.scrollHeight >= 150;
        setShowMoreBtn(showMore && collapse);
      }
    };

    updateScrollHeight();

    const resizeObserver = new ResizeObserver(updateScrollHeight);
    if (codeRef.current) {
      resizeObserver.observe(codeRef.current);
    }

    return () => {
      if (codeRef.current) {
        resizeObserver.unobserve(codeRef.current);
      }
    };
  }, [collapse]);

  useEffect(() => {
    if (codeRef.current) {
      delete codeRef.current.dataset.highlighted;
      hljs.highlightElement(codeRef.current);
    }
  }, [parsedChildren]);

  const onCopy = () => {
    copyToClipboard(parsedChildren, '复制成功');
  };

  const onZoomIn = () => {
    jsBridgePostMessage({
      command: 'zoomInCodeBlock',
      data: {
        code: parsedChildren,
        language: className?.replace('language-', '') ?? '',
      },
    });
  };

  const onInsert = () => {
    // TODO:缺少参数
    jsBridgePostMessage({
      command: 'insertCode',
      data: {
        code: parsedChildren,
      },
    });
  };

  if (inline) {
    return (
      <span className={classNames(styles.inlineCode, className)} {...rest}>
        {parsedChildren}
      </span>
    );
  } else {
    return (
      parsedChildren && (
        <pre
          className={classNames(styles.code, {
            [styles.collapse]: collapse,
          })}
        >
          <div className={styles.operationList}>
            <Tooltip title="放大">
              <ZoomSVG onClick={onZoomIn} className={styles.operationItem} />
            </Tooltip>
            <Tooltip title="复制">
              <CopySVG onClick={onCopy} className={styles.operationItem} />
            </Tooltip>
            <Tooltip title="插入">
              <InsertSVG onClick={onInsert} className={styles.operationItem} />
            </Tooltip>
          </div>
          <code className={className} {...rest} ref={codeRef}>
            {parsedChildren}
          </code>
          {showMoreBtn && (
            <div
              className={styles.collapseWrapper}
              onClick={() => setCollapse(false)}
            >
              <span className={styles.collapseBtn}>
                <img src={codeCollapse} />
              </span>
            </div>
          )}
        </pre>
      )
    );
  }
};

export default memo(CodeRender);
