import { ReactComponent as ImgSVG } from '@/assets/footer/img.svg';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import getImgExtensionFromBase64 from '@/utils/getImgExtensionFromBase64';
import getRandomFileName from '@/utils/getRandomFileName';
import { message, Popover } from 'antd';
import { v4 as uuid } from 'uuid';
import styles from './index.module.less';

interface PreviewImgProps {
  imgArr: Array<string>;
  setImgArr: (imgArr: Array<string>) => void;
}

const PreviewImg: React.FC<PreviewImgProps> = ({ imgArr, setImgArr }) => {
  const handleImgClick = (item: string) => {
    // 本地预览
    const extension = getImgExtensionFromBase64(item);
    if (!extension) {
      message.error('获取文件后缀失败');
      return;
    }

    jsBridgePostMessage({
      command: 'picPreview',
      data: {
        title: getRandomFileName(extension as string),
        content: item.split(',')[1],
        url: '',
      },
    });
  };

  const handleClose = (target: number) => {
    const newImgArray = imgArr.filter((_, index: number) => index !== target);
    setImgArr(newImgArray);
  };

  if (!imgArr?.length) return null;

  return (
    <div className={styles.outerBox}>
      {imgArr?.map((item: string, index: number) => (
        <Popover
          key={uuid()}
          content={
            <div className={styles.previewContent}>
              <img src={item} alt={`图片 ${index + 1}`} />
            </div>
          }
          title={`图片 ${index + 1}`}
          trigger="hover"
          placement="top"
          overlayClassName={styles.previewPopover}
        >
          <div className={styles.extag} onClick={() => handleImgClick(item)}>
            <div className={styles.iconWrapper}>
              <ImgSVG />
            </div>
            <span>图片 {index + 1}</span>
            <b
              onClick={(e) => {
                e.stopPropagation();
                handleClose(index);
              }}
            >
              ×
            </b>
          </div>
        </Popover>
      ))}
    </div>
  );
};

export default PreviewImg;
