import { ReactComponent as ImgUploadSVG } from '@/assets/footer/img_upload.svg';
import { Tooltip } from 'antd';
import { useCallback, useEffect } from 'react';
import styles from './index.module.less';
import useFileProcessing from './useFileProcessing';

interface ImgBtnProps {
  imgArr: Array<string>;
  setUploading?: (uploading: boolean) => void;
  setImgArr: (url: Array<string>) => void;
  chatId: string;
  tabRef?: React.RefObject<HTMLDivElement>;
}

const ImgBtn: React.FC<ImgBtnProps> = ({
  setUploading,
  setImgArr,
  imgArr,
  chatId,
  tabRef,
}) => {
  const { processFiles } = useFileProcessing(imgArr, setImgArr);

  // 处理文件上传
  const handleFileChange = useCallback(
    async (event: React.ChangeEvent<HTMLInputElement>) => {
      const files = event.target.files;
      if (!files?.length) return;

      if (setUploading) {
        setUploading(true);
        try {
          await processFiles(files);
        } finally {
          setUploading(false);
        }
      } else {
        await processFiles(files);
      }
    },
    [processFiles, setUploading],
  );

  // 处理拖拽上传
  useEffect(() => {
    const container = tabRef?.current;
    if (!container) return;

    const handleDragOver = (e: DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
    };

    const handleDrop = async (e: DragEvent) => {
      e.preventDefault();
      e.stopPropagation();

      const files = e.dataTransfer?.files;
      if (files?.length) {
        if (setUploading) {
          setUploading(true);
          try {
            await processFiles(files);
          } finally {
            setUploading(false);
          }
        } else {
          await processFiles(files);
        }
      }
    };

    container.addEventListener('dragover', handleDragOver);
    container.addEventListener('drop', handleDrop);
    return () => {
      container.removeEventListener('dragover', handleDragOver);
      container.removeEventListener('drop', handleDrop);
    };
  }, [processFiles, setUploading]);

  return (
    <Tooltip title="上传图片">
      <div className={styles.toolbar_btn} style={{ top: 1 }}>
        <label htmlFor={`upload-input-${chatId}`} style={{ cursor: 'pointer' }}>
          <ImgUploadSVG />
        </label>
        <input
          id={`upload-input-${chatId}`}
          type="file"
          accept="image/*"
          multiple
          style={{ display: 'none' }}
          onChange={handleFileChange}
        />
      </div>
    </Tooltip>
  );
};

export default ImgBtn;
