import { ReactComponent as SendSVG } from '@/assets/footer/send.svg';
import { ReactComponent as SendingSVG } from '@/assets/footer/sending.svg';
import { Tooltip } from 'antd';
import styles from './index.module.less';

interface SendBtnProps {
  loading: boolean;
  inputValue: string;
  onSendQuestion: () => void;
  uploading?: boolean;
  getFileLoading?: boolean;
}

const SendBtn: React.FC<SendBtnProps> = ({
  loading,
  inputValue,
  onSendQuestion,
  uploading = false,
  getFileLoading = false,
}) => {
  const canSend = () => {
    return !!inputValue && !uploading && !getFileLoading;
  };

  return (
    <>
      {loading ? (
        <Tooltip title="正在回答">
          <SendingSVG className={styles.spin} />
        </Tooltip>
      ) : !canSend() ? (
        <Tooltip title="内容为空，禁止发送">
          <SendSVG className={styles.noSend} />
        </Tooltip>
      ) : (
        <Tooltip title="点击发送">
          <SendSVG onClick={onSendQuestion} className={styles.send} />
        </Tooltip>
      )}
    </>
  );
};

export default SendBtn;
