import arrowDownIcon from '@/assets/common/arrow-down.svg';
import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import { useGlobalStore } from '@/store';
import { history } from '@umijs/max';
import { Dropdown } from 'antd';
import { useState } from 'react';
import styles from './index.module.less';

interface MenuItemType {
  key: 'chat' | 'agent';
  label: string;
}

const ModeSwitch: React.FC = () => {
  const { pluginConfig, setPluginConfig } = useGlobalStore();
  const { mode } = pluginConfig;
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  // 菜单选项
  const menuItems: MenuItemType[] = [
    { key: 'chat', label: 'Chat' },
    { key: 'agent', label: 'Agent' },
  ];

  // 当前选中的模式
  const curMode = menuItems.find((item) => item.key === mode) || menuItems[0];

  const handleModeClick = ({ key }: { key: string }) => {
    const selected = menuItems.find(
      (item) => item.key === (key as 'chat' | 'agent'),
    );
    if (selected) {
      setPluginConfig({
        ...pluginConfig,
        mode: selected.key,
      });
      jsBridgePostMessage({
        command: 'setPluginConfig',
        data: {
          mode: selected.key,
        },
      });
      history.push(selected.key === 'agent' ? '/chat' : '/oldChat');
    }
  };

  const handleDropdownVisibleChange = (visible: boolean) => {
    setIsDropdownOpen(visible);
  };

  return (
    <Dropdown
      menu={{ items: menuItems, onClick: handleModeClick }}
      trigger={['click']}
      onOpenChange={handleDropdownVisibleChange}
    >
      <div className={styles.mode_btn} onClick={(e) => e.preventDefault()}>
        <span className={styles.mode_btn_text}>{curMode.label}</span>
        <img
          src={arrowDownIcon}
          className={`${styles.arrow_icon} ${
            isDropdownOpen ? styles.arrow_rotated : ''
          }`}
          alt="arrow"
        />
      </div>
    </Dropdown>
  );
};

export default ModeSwitch;
