import arrowDownIcon from '@/assets/common/arrow-down.svg';
import { useGlobalStore } from '@/store';
import { Tooltip } from 'antd';
import { useState } from 'react';
import styles from './index.module.less';

const ModelBtn: React.FC = () => {
  const { displayModel } = useGlobalStore();
  const [isDropdownOpen, setIsDropdownOpen] = useState<boolean>(false);

  const handleDropdownVisibleChange = (visible: boolean) => {
    setIsDropdownOpen(visible);
  };

  return (
    <Tooltip title={displayModel || 'choose model'}>
      <div
        className={styles.model_btn}
        onClick={(e) => {
          e.preventDefault();
          handleDropdownVisibleChange(!isDropdownOpen);
        }}
      >
        <span className={styles.model_btn_text}>{displayModel || 'model'}</span>
        <img
          src={arrowDownIcon}
          className={`${styles.arrow_icon} ${
            isDropdownOpen ? styles.arrow_rotated : ''
          }`}
          alt="arrow"
        />
      </div>
    </Tooltip>
  );
};

export default ModelBtn;
