import { modelConfig } from '@/pages/Agentic/modelConfig';
import { cancelRunning } from '@/services/Api/agentic';
import { useGlobalStore } from '@/store';
import { StopOutlined } from '@ant-design/icons';
import { message, Tag } from 'antd';
import styles from './index.module.less';

interface AbortProps {
  onAbort: () => void;
  chatId: string;
}

const Abort: React.FC<AbortProps> = ({ onAbort, chatId }) => {
  const {
    projectConfig: { sideCarIDEInfo },
    pluginConfig: { provider },
  } = useGlobalStore();

  // 中断对话
  const handleClick = async () => {
    // 不再接收后续返回的消息
    onAbort();

    if (!sideCarIDEInfo) {
      message.error('sideCar信息为空');
      return;
    }

    const { editorUrl, sideCarPort } = sideCarIDEInfo;

    // 通知 sideCar 中断
    await cancelRunning(
      {
        session_id: chatId,
        editor_url: editorUrl,
        access_token: '',
        model_configuration: {
          ...modelConfig,
          model_name: provider.model_name,
          selected_provider: provider.selected_provider,
          selected_provider_api_key: provider.selected_provider_api_key,
        },
      },
      `http://localhost:${sideCarPort}`,
    );
  };
  return (
    <div className={styles.footer_top} onClick={handleClick}>
      <Tag
        className={styles.footer_top_tag}
        icon={<StopOutlined />}
        color="default"
      >
        停止生成
      </Tag>
    </div>
  );
};
export default Abort;
